#!/usr/bin/env node
// typeship — MCP server. Generated by typeship — https://typeship.dev
// Speaks MCP 2026-07-28 (stateless: per-request _meta, server/discover; no
// initialize handshake, no sessions). Two transports, zero dependencies:
//   node mcp.js            stdio (newline-delimited JSON-RPC 2.0)
//   node mcp.js --http     Streamable HTTP on PORT (default 3000)
// handleHttp() is exported for serverless/worker runtimes.
// In HTTP mode an incoming Authorization header is forwarded to the
// upstream API (per-request passthrough); stdio resolves auth from the
// environment, then from credentials/config saved by the CLI's `login`
// and `config` commands (same files, so one login covers both bins).

import { readFileSync, realpathSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { TypeshipClient, formatDebugEvent, type DebugEvent } from "./index.js";
import { GLOBALS, OPS, buildArgs, missingRequired, type OpSpec } from "./ops.js";

const BIN = "typeship";
const SERVER_NAME = "typeship-mcp";
const SERVER_VERSION = "1.0.0";
/** Protocol revisions this server speaks. 2026-07-28 is the stateless
 * revision: every request carries its version and client capabilities in
 * _meta, and there is no initialize handshake. Legacy (initialize-based)
 * revisions are not served; an initialize request gets an error naming
 * this list, as the spec asks of modern-only servers. */
const SUPPORTED_PROTOCOL_VERSIONS = ["2026-07-28"];
const SERVER_INFO = { name: SERVER_NAME, title: "typeship", version: SERVER_VERSION };
/** The tool list is fixed at generation, so clients may cache it for an
 * hour and shared caches may hold it (identical for every caller). */
const TOOLS_TTL_MS = 60 * 60 * 1000;
const META_VERSION = "io.modelcontextprotocol/protocolVersion";
const META_CLIENT_CAPS = "io.modelcontextprotocol/clientCapabilities";
const META_SERVER_INFO = "io.modelcontextprotocol/serverInfo";
const DEFAULT_BASE_URL = "https://typeship.dev/api/v1";
const AUTH_SCALARS: { option: string; flag: string; env: string }[] = [{"option":"bearerToken","flag":"token","env":"TYPESHIP_TOKEN"}];
const BASIC: { envUser: string; envPass: string } | null = null;
const ENVIRONMENTS: Record<string, string> = {};
const DOCS_URL_DEFAULT: string | null = "https://typeship.dev";
/** "meta" collapses per-operation tools into search/read/execute so huge
 * APIs don't flood agent context with hundreds of tools. */
const TOOL_MODE: "operations" | "meta" = "operations";
/** Authorization server for OAuth discovery (RFC 9728), from the spec. */
const OAUTH_ISSUER: string | null = null;

function configDir(): string {
  return join(process.env.XDG_CONFIG_HOME ?? join(homedir(), ".config"), BIN);
}

function readJson<T>(file: string): T | null {
  try {
    return JSON.parse(readFileSync(join(configDir(), file), "utf8")) as T;
  } catch {
    return null;
  }
}

function makeClient(): TypeshipClient {
  const stored = readJson<{
    scalars?: Record<string, string>;
    basic?: { username: string; password: string };
    oauth?: { accessToken: string };
  }>("credentials.json");
  const config = readJson<{ baseUrl?: string; environment?: string }>("config.json");
  const options: Record<string, unknown> = {};
  const baseUrl = process.env["TYPESHIP_BASE_URL"]
    ?? config?.baseUrl
    ?? (config?.environment !== undefined ? ENVIRONMENTS[config.environment] : undefined)
    ?? DEFAULT_BASE_URL ?? undefined;
  if (baseUrl === undefined) {
    // Thrown, not exited: the agent gets an isError result naming the fix
    // instead of a server that vanished mid-conversation.
    throw new Error("No base URL configured: set TYPESHIP_BASE_URL in the MCP server's environment, or run '" + BIN + " config set base-url <url>'.");
  }
  options.baseUrl = baseUrl;
  for (const a of AUTH_SCALARS) {
    const v = process.env[a.env] ?? stored?.scalars?.[a.option];
    if (v !== undefined) options[a.option] = v;
  }
  if (BASIC) {
    const username = process.env[BASIC.envUser] ?? stored?.basic?.username;
    const password = process.env[BASIC.envPass] ?? stored?.basic?.password;
    if (username !== undefined && password !== undefined) options.basicAuth = { username, password };
  }
  if (options.bearerToken === undefined && stored?.oauth?.accessToken !== undefined) {
    options.bearerToken = stored.oauth.accessToken;
  }
  for (const g of GLOBALS) {
    const value = process.env["TYPESHIP_" + g.envSuffix];
    if (value !== undefined) options[g.option] = value;
  }
  if (process.env["TYPESHIP_DEBUG"] === "1") {
    options.debug = (event: DebugEvent) => process.stderr.write(formatDebugEvent(BIN + "-mcp", event) + "\n");
  }
  return new TypeshipClient(options as never);
}

let clientInstance: TypeshipClient | undefined;
function getClient(): TypeshipClient {
  return (clientInstance ??= makeClient());
}

interface JsonRpcRequest {
  jsonrpc: "2.0";
  id?: number | string | null;
  method: string;
  params?: Record<string, unknown>;
}

const EXECUTE_TOOL = {
  name: "execute",
  description: "Execute any API operation by name. Discover operations with search_docs; read_docs <operation> shows its arguments. Arguments are passed as a JSON object keyed by parameter name.",
  inputSchema: {
    type: "object",
    properties: {
      operation: { type: "string", description: "Operation tool name, e.g. accounts_createAccount" },
      arguments: { type: "object", description: "Operation arguments keyed by parameter name" },
    },
    required: ["operation"],
  },
};

/** Tool annotations from the HTTP method (spec: hints, untrusted by
 * clients). Clients such as Claude Code use readOnlyHint to auto-approve
 * reads and destructiveHint to confirm deletes. */
function annotationsFor(op: OpSpec): Record<string, unknown> {
  const m = op.httpMethod.toUpperCase();
  return {
    title: op.summary ?? op.tool,
    readOnlyHint: m === "GET" || m === "HEAD",
    destructiveHint: m === "DELETE",
    idempotentHint: m === "GET" || m === "HEAD" || m === "PUT" || m === "DELETE",
    openWorldHint: true,
  };
}

function toolDefinitions(): unknown[] {
  if (TOOL_MODE === "meta") {
    return [
      {
        name: "search_docs",
        description: "Search this API's " + OPS.length + " operations and, when a docs site is configured, its guides. Start here to find the operation you need.",
        inputSchema: { type: "object", properties: { query: { type: "string" } }, required: ["query"] },
      },
      {
        name: "read_docs",
        description: "Read an operation's full reference (arguments, requirements) by tool name, or a docs-site guide page.",
        inputSchema: { type: "object", properties: { page: { type: "string" } }, required: ["page"] },
      },
      EXECUTE_TOOL,
    ];
  }
  return [
    ...OPS.map((op) => ({
      name: op.tool,
      title: op.summary ?? op.tool,
      description: op.toolDescription,
      annotations: annotationsFor(op),
      inputSchema: op.select
        ? {
            ...op.inputSchema,
            properties: {
              ...(op.inputSchema.properties as Record<string, unknown>),
              select: { type: "string", description: 'GraphQL selection set override, e.g. "{ id name }"' },
            },
          }
        : op.inputSchema,
    })),
    {
      name: "search_docs",
      description: "Search this API's reference (operations, parameters) and, when a docs site is configured, its guides.",
      inputSchema: { type: "object", properties: { query: { type: "string" } }, required: ["query"] },
    },
    {
      name: "read_docs",
      description: "Read a documentation page: an operation reference (e.g. \"accounts.createAccount\") or a docs-site guide page by name or URL.",
      inputSchema: { type: "object", properties: { page: { type: "string" } }, required: ["page"] },
    },
  ];
}

// ---- docs tools: spec reference + docs-site prose (llms.txt) ---------------

function docsSiteUrl(): string | null {
  const config = readJson<{ docsUrl?: string }>("config.json");
  return config?.docsUrl ?? DOCS_URL_DEFAULT;
}

async function fetchDocs(pathOrFile: string): Promise<string | null> {
  const base = docsSiteUrl();
  const url = /^https?:\/\//.test(pathOrFile)
    ? pathOrFile
    : base === null
      ? null
      : base.replace(/\/+$/, "") + "/" + pathOrFile.replace(/^\/+/, "");
  if (url === null) return null;
  try {
    const response = await fetch(url, {
      headers: { Accept: "text/markdown, text/plain, */*" },
      signal: AbortSignal.timeout(10_000),
    });
    if (!response.ok) return null;
    return await response.text();
  } catch {
    return null;
  }
}

function referenceText(op: OpSpec): string {
  const lines = [
    op.tool + ": " + op.httpMethod + " " + op.path + (op.paginated ? " (paginated)" : ""),
    ...(op.summary ? [op.summary] : []),
    ...(op.description ? ["", op.description.trim()] : []),
  ];
  if (op.params.length > 0) {
    lines.push("", "Arguments:");
    for (const p of op.params) {
      lines.push(
        "  " + p.name + " (" + (p.enum ? p.enum.join("|") : p.type) + (p.required ? ", required" : "") + ")" +
        (p.description ? ": " + p.description.trim().split("\n")[0] : ""),
      );
    }
  }
  return lines.join("\n");
}

async function docsSearch(query: string): Promise<string> {
  const term = query.toLowerCase();
  const sections: string[] = [];
  const refMatches = OPS.filter((op) =>
    (op.tool + " " + op.path + " " + (op.summary ?? "") + " " + (op.description ?? "") + " " +
      op.params.map((p) => p.name).join(" ")).toLowerCase().includes(term));
  if (refMatches.length > 0) {
    sections.push("Reference matches:\n" + refMatches.slice(0, 15).map((op) =>
      "- " + op.tool + ": " + (op.summary ?? op.httpMethod + " " + op.path)).join("\n"));
  }
  const prose = await fetchDocs("llms-full.txt");
  if (prose !== null) {
    let heading = "";
    const proseMatches: string[] = [];
    for (const line of prose.split("\n")) {
      if (/^#{1,3} /.test(line)) heading = line.replace(/^#+ /, "").trim();
      else if (line.toLowerCase().includes(term) && proseMatches.length < 15) {
        proseMatches.push("- [" + heading + "] " + line.trim().slice(0, 160));
      }
    }
    if (proseMatches.length > 0) sections.push("Guide matches:\n" + proseMatches.join("\n"));
  }
  if (sections.length === 0) {
    return "No matches for: " + query + (docsSiteUrl() === null ? " (no docs site configured; only the API reference was searched)" : "");
  }
  return sections.join("\n\n");
}

async function docsRead(page: string): Promise<{ text: string; isError: boolean }> {
  const opMatch = OPS.find((op) => op.tool === page || op.tool.toLowerCase() === page.toLowerCase().replace(/\./g, "_"));
  if (opMatch) return { text: referenceText(opMatch), isError: false };
  let target = page;
  if (!/^https?:\/\//.test(target)) {
    const index = await fetchDocs("llms.txt");
    const linked = index?.match(/\((https?:[^)]+)\)/g)?.map((m) => m.slice(1, -1)) ?? [];
    const hit = linked.find((u) => u.toLowerCase().includes(target.toLowerCase()));
    if (hit !== undefined) target = hit;
  }
  const text = await fetchDocs(target);
  if (text === null) {
    return {
      text: docsSiteUrl() === null
        ? "No docs site is configured for this server, and no operation matches \"" + page + "\"."
        : "Couldn't fetch \"" + page + "\". Use search_docs to find pages.",
      isError: true,
    };
  }
  return { text, isError: false };
}

interface ToolOutcome {
  text: string;
  isError: boolean;
  /** JSON value behind the text, for structuredContent. */
  structured?: unknown;
}

async function callTool(
  op: OpSpec,
  args: Record<string, unknown>,
  authHeader?: string,
): Promise<ToolOutcome> {
  const values: Record<string, unknown> = {};
  for (const p of op.params) {
    if (args[p.name] !== undefined) values[p.name] = args[p.name];
  }
  const missing = missingRequired(op, values).filter((name) => !(op.bodyStyle === "data" && name === "body" && args.body !== undefined));
  if (missing.length > 0) {
    return { text: "Missing required argument(s): " + missing.join(", "), isError: true };
  }
  const callArgs = buildArgs(
    op,
    values,
    op.bodyStyle === "data" ? args.body : undefined,
    typeof args.select === "string" ? args.select : undefined,
  );
  if (authHeader) {
    callArgs.push({ headers: { Authorization: authHeader } });
  }
  try {
    const target = (getClient() as unknown as Record<string, Record<string, (...a: unknown[]) => unknown>>)[op.resource]!;
    const result = await (target[op.method]!(...callArgs) as Promise<{ ok: boolean; data?: unknown; error?: unknown }>);
    if (result.ok) {
      if (op.paginated) {
        // nextPage carries the exact arguments for the following page, so an
        // agent can continue without knowing the API's pagination style.
        const page = result.data as { items: unknown[]; hasNextPage(): boolean; nextPageParams(): Record<string, unknown> | null };
        const next = page.nextPageParams();
        const structured = { items: page.items, hasMore: next !== null, ...(next !== null ? { nextPage: next } : {}) };
        return { text: JSON.stringify(structured, null, 2), isError: false, structured };
      }
      const structured = result.data ?? { ok: true };
      return { text: JSON.stringify(structured, null, 2), isError: false, structured };
    }
    const e = result.error as { name?: string; message?: string; status?: number; body?: unknown };
    const structured = { error: e?.name ?? "Error", message: e?.message, status: e?.status, body: e?.body };
    return { text: JSON.stringify(structured, null, 2), isError: true, structured };
  } catch (e) {
    return { text: (e as Error).message ?? "Tool call failed", isError: true };
  }
}

// ---- JSON-RPC / MCP 2026-07-28 protocol layer ------------------------------

interface JsonRpcMessage {
  jsonrpc?: string;
  id?: number | string | null;
  method: string;
  params?: Record<string, unknown>;
}

/** What handleRpc hands back: the JSON-RPC message to send (null for a
 * notification) and the HTTP status the Streamable HTTP transport should
 * use for it (stdio ignores it). */
interface RpcOutcome {
  message: Record<string, unknown> | null;
  status: number;
}

const rpcError = (id: unknown, code: number, message: string, status: number, data?: unknown): RpcOutcome => ({
  message: { jsonrpc: "2.0", id: id ?? null, error: { code, message, ...(data !== undefined ? { data } : {}) } },
  status,
});

/** Shape check before anything else: batches (removed in 2025-06-18) and
 * non-objects get an error instead of a dead server. */
function asJsonRpc(message: unknown): JsonRpcMessage | RpcOutcome {
  if (Array.isArray(message)) {
    return rpcError(null, -32600, "JSON-RPC batching is not supported; send one message per request.", 400);
  }
  const isObject = message !== null && typeof message === "object";
  const method = isObject ? (message as { method?: unknown }).method : undefined;
  if (!isObject || typeof method !== "string") {
    return rpcError(null, -32600, "Invalid Request: expected a JSON-RPC 2.0 message with a string method.", 400);
  }
  return message as JsonRpcMessage;
}

/** Per-request protocol metadata (2026-07-28 basic/_meta): protocolVersion
 * and clientCapabilities are REQUIRED on every request. Missing -> -32602
 * (400 on HTTP); unsupported version -> -32022 listing what we speak. */
function checkRequestMeta(request: JsonRpcMessage): RpcOutcome | { version: string } {
  const meta = (request.params?._meta ?? undefined) as Record<string, unknown> | undefined;
  const version = meta?.[META_VERSION];
  const caps = meta?.[META_CLIENT_CAPS];
  if (typeof version !== "string") {
    return rpcError(request.id, -32602, "Invalid params: params._meta[\"" + META_VERSION + "\"] is required on every request (MCP 2026-07-28).", 400);
  }
  if (!SUPPORTED_PROTOCOL_VERSIONS.includes(version)) {
    return rpcError(request.id, -32022, "Unsupported protocol version", 400, { supported: SUPPORTED_PROTOCOL_VERSIONS, requested: version });
  }
  if (caps === null || typeof caps !== "object" || Array.isArray(caps)) {
    return rpcError(request.id, -32602, "Invalid params: params._meta[\"" + META_CLIENT_CAPS + "\"] is required on every request (MCP 2026-07-28).", 400);
  }
  return { version };
}

/** Requests whose client cancelled them (stdio notifications/cancelled):
 * the spec says the server MUST NOT send further messages for them. */
const cancelled = new Set<string | number>();

async function handleRpc(
  incoming: unknown,
  authHeader?: string,
): Promise<RpcOutcome> {
  const parsed = asJsonRpc(incoming);
  if ("status" in parsed) return parsed;
  const request = parsed;
  const id = request.id;

  // Notifications: no id, no reply. Only notifications/cancelled means anything here.
  if (id === undefined || id === null) {
    if (request.method === "notifications/cancelled") {
      const target = request.params?.requestId;
      if (typeof target === "string" || typeof target === "number") cancelled.add(target);
    }
    return { message: null, status: 202 };
  }

  // Legacy clients open with initialize; name what we do speak so their one
  // visible error is actionable (spec: modern-only servers SHOULD do this).
  if (request.method === "initialize") {
    return rpcError(id, -32601,
      "This server speaks MCP " + SUPPORTED_PROTOCOL_VERSIONS.join(", ") + " only (stateless, no initialize handshake). Upgrade the client, or send requests with params._meta[\"" + META_VERSION + "\"].",
      400, { supported: SUPPORTED_PROTOCOL_VERSIONS });
  }

  const meta = checkRequestMeta(request);
  if ("status" in meta) return meta;

  const complete = (result: Record<string, unknown>): RpcOutcome => ({
    message: { jsonrpc: "2.0", id, result: { resultType: "complete", ...result, _meta: { [META_SERVER_INFO]: SERVER_INFO } } },
    status: 200,
  });

  switch (request.method) {
    case "server/discover":
      return complete({
        supportedVersions: SUPPORTED_PROTOCOL_VERSIONS,
        capabilities: { tools: {} },
        instructions: "Every operation of " + "typeship" + " is a tool. Use search_docs to find operations and read_docs for an operation's full argument reference. Paginated tools return items, hasMore, and nextPage (the exact arguments for the following page).",
        ttlMs: TOOLS_TTL_MS,
        cacheScope: "public",
      });
    case "tools/list":
      return complete({ tools: toolDefinitions(), ttlMs: TOOLS_TTL_MS, cacheScope: "public" });
    case "tools/call": {
      const name = request.params?.name;
      const toolResult = (outcome: ToolOutcome): RpcOutcome => complete({
        content: [{ type: "text", text: outcome.text }],
        ...(outcome.structured !== undefined ? { structuredContent: outcome.structured } : {}),
        isError: outcome.isError,
      });
      if (name === "search_docs" || name === "read_docs") {
        const docArgs = (request.params?.arguments ?? {}) as { query?: unknown; page?: unknown };
        if (name === "search_docs") {
          if (typeof docArgs.query !== "string") return rpcError(id, -32602, "search_docs requires a query string", 400);
          return toolResult({ text: await docsSearch(docArgs.query), isError: false });
        }
        if (typeof docArgs.page !== "string") return rpcError(id, -32602, "read_docs requires a page string", 400);
        return toolResult(await docsRead(docArgs.page));
      }
      if (name === "execute") {
        const executeArgs = (request.params?.arguments ?? {}) as { operation?: unknown; arguments?: unknown };
        if (typeof executeArgs.operation !== "string") return rpcError(id, -32602, "execute requires an operation name", 400);
        const wanted = executeArgs.operation;
        const target = OPS.find((o) => o.tool === wanted || o.tool === wanted.replace(/\./g, "_"));
        if (!target) return rpcError(id, -32602, "Unknown operation: " + wanted + ". Use search_docs to find operations.", 400);
        const opArgs = (executeArgs.arguments ?? {}) as Record<string, unknown>;
        return toolResult(await callTool(target, opArgs, authHeader));
      }
      const op = OPS.find((o) => o.tool === name);
      if (!op) return rpcError(id, -32602, "Unknown tool: " + String(name), 400);
      const args = (request.params?.arguments ?? {}) as Record<string, unknown>;
      return toolResult(await callTool(op, args, authHeader));
    }
    default:
      return rpcError(id, -32601, "Method not found: " + request.method, 404);
  }
}

// ---- Streamable HTTP transport ---------------------------------------------

/** Origins allowed to call the HTTP transport from a browser. Non-browser
 * MCP clients send no Origin and are always accepted; the spec requires
 * validating the header when present (DNS-rebinding defense), so browser
 * callers must be same-host, localhost, or listed in
 * TYPESHIP_MCP_ALLOWED_ORIGINS (comma-separated, "*" for any). */
function originAllowed(request: Request): boolean {
  const origin = request.headers.get("origin");
  if (origin === null) return true;
  const allowed = (process.env["TYPESHIP_MCP_ALLOWED_ORIGINS"] ?? "").split(",").map((s) => s.trim()).filter(Boolean);
  if (allowed.includes("*") || allowed.includes(origin)) return true;
  try {
    const o = new URL(origin);
    if (o.host === new URL(request.url).host) return true;
    return ["localhost", "127.0.0.1", "[::1]"].includes(o.hostname);
  } catch {
    return false;
  }
}

function corsHeaders(request: Request): Record<string, string> {
  return {
    "Access-Control-Allow-Origin": request.headers.get("origin") ?? "*",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization, Accept, MCP-Protocol-Version, Mcp-Method, Mcp-Name",
    Vary: "Origin",
  };
}

function protectedResourceMetadata(origin: string): Record<string, unknown> {
  return {
    resource: origin,
    ...(OAUTH_ISSUER ? { authorization_servers: [OAUTH_ISSUER] } : {}),
    bearer_methods_supported: ["header"],
  };
}

/** Header values may arrive as =?base64?...?= when not header-safe. */
function decodeHeaderValue(value: string): string {
  if (value.startsWith("=?base64?") && value.endsWith("?=")) {
    try {
      // atob + TextDecoder rather than Buffer: works in Node and worker runtimes alike.
      return new TextDecoder().decode(Uint8Array.from(atob(value.slice(9, -2)), (c) => c.charCodeAt(0)));
    } catch {
      return value;
    }
  }
  return value;
}

/** Streamable HTTP mirrors body fields into headers so intermediaries can
 * route without parsing; a server that reads the body MUST check they
 * agree (400 + -32020 HeaderMismatch), including when they're missing. */
function checkRequestHeaders(request: Request, message: JsonRpcMessage): RpcOutcome | null {
  const id = message.id;
  const version = request.headers.get("mcp-protocol-version");
  const bodyVersion = (message.params?._meta as Record<string, unknown> | undefined)?.[META_VERSION];
  if (version === null) return rpcError(id, -32020, "Header mismatch: MCP-Protocol-Version header is required", 400);
  if (typeof bodyVersion === "string" && version !== bodyVersion) {
    return rpcError(id, -32020, "Header mismatch: MCP-Protocol-Version header '" + version + "' does not match body value '" + bodyVersion + "'", 400);
  }
  const method = request.headers.get("mcp-method");
  if (method === null) return rpcError(id, -32020, "Header mismatch: Mcp-Method header is required", 400);
  if (method !== message.method) {
    return rpcError(id, -32020, "Header mismatch: Mcp-Method header '" + method + "' does not match body value '" + message.method + "'", 400);
  }
  if (message.method === "tools/call") {
    const nameHeader = request.headers.get("mcp-name");
    const bodyName = message.params?.name;
    if (nameHeader === null) return rpcError(id, -32020, "Header mismatch: Mcp-Name header is required for tools/call", 400);
    if (typeof bodyName === "string" && decodeHeaderValue(nameHeader) !== bodyName) {
      return rpcError(id, -32020, "Header mismatch: Mcp-Name header '" + nameHeader + "' does not match body value '" + bodyName + "'", 400);
    }
  }
  return null;
}

/** Fetch-style handler: mount in any runtime (workers, serverless, node).
 * Never rejects: every failure is an HTTP or JSON-RPC error response. */
export async function handleHttp(request: Request): Promise<Response> {
  const url = new URL(request.url);
  const cors = corsHeaders(request);
  const json = (status: number, body: unknown, extra: Record<string, string> = {}) =>
    new Response(JSON.stringify(body), { status, headers: { ...cors, "Content-Type": "application/json", ...extra } });

  if (request.method === "OPTIONS") {
    return new Response(null, { status: originAllowed(request) ? 204 : 403, headers: cors });
  }
  if (!originAllowed(request)) {
    return json(403, { jsonrpc: "2.0", error: { code: -32600, message: "Origin not allowed. Set TYPESHIP_MCP_ALLOWED_ORIGINS to permit browser callers." } });
  }
  if (url.pathname.endsWith("/.well-known/oauth-protected-resource")) {
    return json(200, protectedResourceMetadata(url.origin));
  }
  if (request.method !== "POST") {
    // GET streams, DELETE (session end) and Mcp-Session-Id belong to earlier
    // revisions; the spec asks modern-only servers to answer 405.
    return json(405, { error: "POST JSON-RPC messages to this endpoint (MCP 2026-07-28, stateless)." }, { Allow: "POST, OPTIONS" });
  }

  const authHeader = request.headers.get("authorization") ?? undefined;
  const envHasAuth = AUTH_SCALARS.some((a) => process.env[a.env] !== undefined);
  if (OAUTH_ISSUER && !authHeader && !envHasAuth) {
    return json(401, { error: "Authorization required." }, {
      "WWW-Authenticate": 'Bearer resource_metadata="' + url.origin + '/.well-known/oauth-protected-resource"',
    });
  }

  let incoming: unknown;
  try {
    incoming = await request.json();
  } catch {
    return json(400, { jsonrpc: "2.0", id: null, error: { code: -32700, message: "Parse error" } });
  }
  const parsed = asJsonRpc(incoming);
  if ("status" in parsed) return json(parsed.status, parsed.message);
  // Header/body agreement is checked for requests; the spec defines no
  // header requirements for notification POSTs.
  if (parsed.id !== undefined && parsed.id !== null && parsed.method !== "initialize") {
    const mismatch = checkRequestHeaders(request, parsed);
    if (mismatch) return json(mismatch.status, mismatch.message);
  }
  let outcome: RpcOutcome;
  try {
    outcome = await handleRpc(parsed, authHeader);
  } catch (e) {
    return json(500, { jsonrpc: "2.0", id: parsed.id ?? null, error: { code: -32603, message: (e as Error).message ?? "Internal error" } });
  }
  if (outcome.message === null) {
    return new Response(null, { status: outcome.status, headers: cors });
  }
  return json(outcome.status, outcome.message);
}

function startHttp(port: number): void {
  void import("node:http").then(({ createServer }) => {
    createServer((req, res) => {
      let body = "";
      req.on("data", (chunk) => (body += chunk));
      req.on("end", () => {
        void handleHttp(
          new Request("http://localhost:" + port + (req.url ?? "/"), {
            method: req.method,
            headers: Object.fromEntries(
              Object.entries(req.headers).map(([k, v]) => [k, Array.isArray(v) ? v.join(", ") : String(v ?? "")]),
            ),
            ...(req.method === "POST" ? { body } : {}),
          }),
        ).then(async (response) => {
          res.statusCode = response.status;
          response.headers.forEach((value, key) => res.setHeader(key, value));
          res.end(await response.text());
        }).catch((e: unknown) => {
          // handleHttp never rejects; this guards the Request construction
          // and socket writes so one bad connection can't take the server.
          process.stderr.write(SERVER_NAME + ": " + ((e as Error).message ?? String(e)) + "\n");
          if (!res.headersSent) res.statusCode = 500;
          res.end();
        });
      });
    }).listen(port, () => {
      process.stderr.write(SERVER_NAME + " listening on http://localhost:" + port + "\n");
    });
  });
}

// ---- stdio transport --------------------------------------------------------

async function startStdio(): Promise<void> {
  // dynamic: node:readline doesn't exist in worker runtimes, and workers
  // never take the stdio path
  const { createInterface } = await import("node:readline");
  const rl = createInterface({ input: process.stdin });
  const write = (message: Record<string, unknown>) => process.stdout.write(JSON.stringify(message) + "\n");
  rl.on("line", (line) => {
    const trimmed = line.trim();
    if (trimmed === "") return;
    let incoming: unknown;
    try {
      incoming = JSON.parse(trimmed);
    } catch {
      write({ jsonrpc: "2.0", id: null, error: { code: -32700, message: "Parse error" } });
      return;
    }
    const id = incoming !== null && typeof incoming === "object" && !Array.isArray(incoming) ? (incoming as { id?: unknown }).id : undefined;
    void handleRpc(incoming)
      .then((outcome) => {
        if (outcome.message === null) return;
        // A cancelled request gets no response (spec: MUST NOT send further messages).
        if ((typeof id === "string" || typeof id === "number") && cancelled.delete(id)) return;
        write(outcome.message);
      })
      .catch((e) => {
        if (id !== undefined) {
          write({ jsonrpc: "2.0", id: id ?? null, error: { code: -32603, message: (e as Error).message ?? "Internal error" } });
        }
      });
  });
  // Spec: exit promptly when stdin closes.
  rl.on("close", () => process.exit(0));
}

/** True when this file is the process entry: `node dist/mcp.js`, the
 * package's `typeship-mcp` bin (a symlink, so compare real paths), or
 * `npx tsx src/mcp.ts`. False when imported (worker.ts, tests). */
function invokedDirectly(): boolean {
  const entry = process.argv[1];
  if (typeof entry !== "string" || entry === "") return false;
  try {
    return realpathSync(entry) === realpathSync(fileURLToPath(import.meta.url));
  } catch {
    return /mcp\.(js|mjs|ts)$/.test(entry);
  }
}
if (invokedDirectly()) {
  const httpFlag = process.argv.indexOf("--http");
  if (httpFlag !== -1) {
    const port = Number(process.argv[httpFlag + 1]) || Number(process.env.PORT) || 3000;
    startHttp(port);
  } else {
    void startStdio();
  }
}
